import { randomUUID } from 'node:crypto'
import { readFile, writeFile, rename, mkdir } from 'node:fs/promises'
import { dirname } from 'node:path'

// The whole library lives in one JSON file. Small enough to read and rewrite
// on every change, which keeps the store honest about what's on disk.
export function createStore(file) {
  let books = null
  // Serializes writes so two concurrent requests can't clobber each other.
  let queue = Promise.resolve()

  async function load() {
    if (books) return books
    try {
      const raw = await readFile(file, 'utf8')
      const parsed = JSON.parse(raw)
      books = Array.isArray(parsed?.books) ? parsed.books : []
    } catch (err) {
      if (err.code !== 'ENOENT') throw err
      books = []
    }
    return books
  }

  async function flush() {
    const tmp = `${file}.tmp`
    await mkdir(dirname(file), { recursive: true })
    await writeFile(tmp, JSON.stringify({ books }, null, 2))
    // Rename is atomic, so a crash mid-write can't truncate the library.
    await rename(tmp, file)
  }

  // Runs `fn` against the loaded books, then persists the result.
  function write(fn) {
    queue = queue.then(async () => {
      await load()
      const result = await fn()
      await flush()
      return result
    })
    return queue
  }

  return {
    async list() {
      const all = await load()
      return {
        reading: all.filter((b) => !b.finishedAt),
        finished: [...all.filter((b) => b.finishedAt)].sort((a, b) =>
          b.finishedAt.localeCompare(a.finishedAt),
        ),
      }
    },

    async get(id) {
      const all = await load()
      return all.find((b) => b.id === id) ?? null
    },

    add({ title, author, notes }, now = new Date()) {
      const clean = {
        title: (title ?? '').trim(),
        author: (author ?? '').trim(),
        notes: (notes ?? '').trim(),
      }
      if (!clean.title) throw new ValidationError('A title is required.')

      return write(() => {
        const book = {
          id: randomUUID().slice(0, 8),
          ...clean,
          addedAt: now.toISOString(),
          finishedAt: null,
        }
        books.push(book)
        return book
      })
    },

    finish(id, now = new Date()) {
      return write(() => {
        const book = books.find((b) => b.id === id)
        if (!book) return null
        // Already finished: keep the original date rather than bumping it.
        book.finishedAt ??= now.toISOString()
        return book
      })
    },

    reopen(id) {
      return write(() => {
        const book = books.find((b) => b.id === id)
        if (!book) return null
        book.finishedAt = null
        return book
      })
    },

    saveNotes(id, notes) {
      return write(() => {
        const book = books.find((b) => b.id === id)
        if (!book) return null
        book.notes = (notes ?? '').trim()
        return book
      })
    },
  }
}

export class ValidationError extends Error {}

