const ENTITIES = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }

export function escapeHtml(value) {
  return String(value ?? '').replace(/[&<>"']/g, (c) => ENTITIES[c])
}

function formatDate(iso) {
  if (!iso) return ''
  return new Date(iso).toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
  })
}

function layout({ title, body }) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeHtml(title)}</title>
<style>
  :root { color-scheme: light dark; --ink: #1c1917; --dim: #78716c; --line: #e7e5e4; --bg: #fafaf9; --card: #fff; --accent: #7c2d12; }
  @media (prefers-color-scheme: dark) {
    :root { --ink: #f5f5f4; --dim: #a8a29e; --line: #292524; --bg: #1c1917; --card: #262322; --accent: #fdba74; }
  }
  * { box-sizing: border-box; }
  body { margin: 0; padding: 2.5rem 1.25rem 4rem; background: var(--bg); color: var(--ink);
    font: 16px/1.6 ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif; }
  main { max-width: 42rem; margin: 0 auto; }
  h1 { font-size: 1.5rem; letter-spacing: -0.01em; margin: 0 0 2rem; }
  h2 { font-size: 0.8rem; text-transform: uppercase; letter-spacing: 0.08em; color: var(--dim);
    margin: 2.5rem 0 0.75rem; font-weight: 600; }
  a { color: inherit; }
  ul { list-style: none; padding: 0; margin: 0; }
  li { border-bottom: 1px solid var(--line); }
  li:first-child { border-top: 1px solid var(--line); }
  .row { display: flex; align-items: baseline; gap: 1rem; padding: 0.85rem 0; }
  .row > a { flex: 1; text-decoration: none; }
  .row > a:hover .title { text-decoration: underline; }
  .title { font-weight: 500; }
  .byline, .meta { color: var(--dim); font-size: 0.875rem; }
  .done .title { color: var(--dim); }
  .empty { color: var(--dim); font-style: italic; padding: 0.85rem 0; }
  form.inline { margin: 0; }
  button { font: inherit; cursor: pointer; border-radius: 6px; border: 1px solid var(--line);
    background: var(--card); color: var(--ink); padding: 0.3rem 0.7rem; font-size: 0.8125rem; }
  button:hover { border-color: var(--dim); }
  button.primary { background: var(--ink); color: var(--bg); border-color: var(--ink);
    padding: 0.55rem 1.1rem; font-size: 0.9375rem; }
  .card { background: var(--card); border: 1px solid var(--line); border-radius: 10px;
    padding: 1.25rem; margin-top: 2.5rem; }
  label { display: block; font-size: 0.8125rem; color: var(--dim); margin-bottom: 0.25rem; }
  .field { margin-bottom: 0.9rem; }
  input, textarea { width: 100%; font: inherit; padding: 0.5rem 0.65rem; border-radius: 6px;
    border: 1px solid var(--line); background: var(--bg); color: var(--ink); }
  textarea { resize: vertical; min-height: 4.5rem; }
  .error { background: #fef2f2; border: 1px solid #fecaca; color: #991b1b; border-radius: 6px;
    padding: 0.6rem 0.8rem; margin-bottom: 1rem; font-size: 0.875rem; }
  .back { color: var(--dim); text-decoration: none; font-size: 0.875rem; }
  .back:hover { color: var(--ink); }
  .detail-title { font-size: 1.75rem; margin: 1.25rem 0 0.25rem; letter-spacing: -0.02em; }
  .detail-author { color: var(--dim); margin: 0 0 1.5rem; }
  .actions { display: flex; gap: 0.6rem; align-items: center; flex-wrap: wrap;
    padding-top: 1.5rem; border-top: 1px solid var(--line); margin-top: 2rem; }
  .notes { white-space: pre-wrap; }
</style>
</head>
<body><main>${body}</main></body>
</html>`
}

function bookRow(book) {
  const done = Boolean(book.finishedAt)
  return `<li>
  <div class="row${done ? ' done' : ''}">
    <a href="/books/${escapeHtml(book.id)}">
      <div class="title">${escapeHtml(book.title)}</div>
      ${book.author ? `<div class="byline">${escapeHtml(book.author)}</div>` : ''}
    </a>
    ${
      done
        ? `<span class="meta">Finished ${escapeHtml(formatDate(book.finishedAt))}</span>`
        : `<form class="inline" method="post" action="/books/${escapeHtml(book.id)}/finish">
             <button type="submit">Mark finished</button>
           </form>`
    }
  </div>
</li>`
}

function section(heading, books, emptyText) {
  const items = books.length
    ? `<ul>${books.map(bookRow).join('')}</ul>`
    : `<p class="empty">${escapeHtml(emptyText)}</p>`
  return `<h2>${escapeHtml(heading)}</h2>${items}`
}

export function renderLibrary({ reading, finished }, { error, draft = {} } = {}) {
  const body = `
<h1>My books</h1>
${section('Currently reading', reading, 'Nothing on the go right now.')}
${section('Finished', finished, "No finished books yet.")}
<form class="card" method="post" action="/books">
  <h2 style="margin-top:0">Add a book</h2>
  ${error ? `<p class="error">${escapeHtml(error)}</p>` : ''}
  <div class="field">
    <label for="title">Title</label>
    <input id="title" name="title" required value="${escapeHtml(draft.title)}">
  </div>
  <div class="field">
    <label for="author">Author</label>
    <input id="author" name="author" value="${escapeHtml(draft.author)}">
  </div>
  <div class="field">
    <label for="notes">Notes (optional)</label>
    <textarea id="notes" name="notes">${escapeHtml(draft.notes)}</textarea>
  </div>
  <button class="primary" type="submit">Add book</button>
</form>`
  return layout({ title: 'My books', body })
}

export function renderBook(book) {
  const done = Boolean(book.finishedAt)
  const id = escapeHtml(book.id)
  const body = `
<a class="back" href="/">&larr; All books</a>
<h1 class="detail-title">${escapeHtml(book.title)}</h1>
<p class="detail-author">${escapeHtml(book.author || 'Unknown author')}</p>
<p class="meta">${
    done
      ? `Finished ${escapeHtml(formatDate(book.finishedAt))}`
      : `Started ${escapeHtml(formatDate(book.addedAt))} &middot; still reading`
  }</p>
<form class="card" method="post" action="/books/${id}/notes">
  <h2 style="margin-top:0">Notes</h2>
  <div class="field">
    <label for="notes">Your notes on this book</label>
    <textarea id="notes" name="notes" rows="8">${escapeHtml(book.notes)}</textarea>
  </div>
  <button type="submit">Save notes</button>
</form>
<div class="actions">
  <form class="inline" method="post" action="/books/${id}/${done ? 'reopen' : 'finish'}">
    <button class="primary" type="submit">${done ? 'Move back to reading' : 'Mark finished'}</button>
  </form>
</div>`
  return layout({ title: `${book.title} — My books`, body })
}

export function renderNotFound() {
  return layout({
    title: 'Not found — My books',
    body: `<h1>No such book</h1>
<p class="empty">That book isn't in the library — the link may be out of date.</p>
<a class="back" href="/">&larr; All books</a>`,
  })
}

