import { createServer } from 'node:http'
import { createStore, ValidationError } from './store.js'
import { renderLibrary, renderBook, renderNotFound } from './views.js'

const MAX_BODY = 64 * 1024

function readBody(req) {
  return new Promise((resolve, reject) => {
    let body = ''
    req.on('data', (chunk) => {
      body += chunk
      if (body.length > MAX_BODY) {
        reject(new ValidationError('That was too much text to save.'))
        req.destroy()
      }
    })
    req.on('end', () => resolve(new URLSearchParams(body)))
    req.on('error', reject)
  })
}

function html(res, status, markup) {
  res.writeHead(status, { 'content-type': 'text/html; charset=utf-8' })
  res.end(markup)
}

function redirect(res, location) {
  // 303 so the browser follows up with a GET and a refresh won't re-post.
  res.writeHead(303, { location })
  res.end()
}

export function createApp(store) {
  return async function handle(req, res) {
    const url = new URL(req.url, `http://${req.headers.host ?? 'localhost'}`)
    const path = url.pathname.replace(/\/+$/, '') || '/'
    const bookMatch = /^\/books\/([\w-]+)(\/finish|\/reopen|\/notes)?$/.exec(path)

    try {
      if (req.method === 'GET' && path === '/') {
        return html(res, 200, renderLibrary(await store.list()))
      }

      if (req.method === 'POST' && path === '/books') {
        const form = await readBody(req)
        const draft = {
          title: form.get('title'),
          author: form.get('author'),
          notes: form.get('notes'),
        }
        try {
          const book = await store.add(draft)
          return redirect(res, `/books/${book.id}`)
        } catch (err) {
          if (!(err instanceof ValidationError)) throw err
          return html(res, 400, renderLibrary(await store.list(), { error: err.message, draft }))
        }
      }

      if (bookMatch) {
        const [, id, action] = bookMatch

        if (req.method === 'GET' && !action) {
          const book = await store.get(id)
          return book ? html(res, 200, renderBook(book)) : html(res, 404, renderNotFound())
        }

        if (req.method === 'POST' && action) {
          const book = action === '/notes'
            ? await store.saveNotes(id, (await readBody(req)).get('notes'))
            : await store[action === '/finish' ? 'finish' : 'reopen'](id)
          return book ? redirect(res, `/books/${id}`) : html(res, 404, renderNotFound())
        }
      }

      return html(res, 404, renderNotFound())
    } catch (err) {
      console.error(err)
      if (res.headersSent) return res.end()
      return html(res, 500, renderNotFound())
    }
  }
}

