import { describe, it, expect, beforeEach, afterEach } from 'vitest'
import { mkdtemp, rm, readFile } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { createStore, ValidationError } from '../src/store.js'

let dir
let file

beforeEach(async () => {
  dir = await mkdtemp(join(tmpdir(), 'books-'))
  file = join(dir, 'books.json')
})

afterEach(() => rm(dir, { recursive: true, force: true }))

describe('createStore', () => {
  it('starts empty when there is no file yet', async () => {
    const store = createStore(file)
    expect(await store.list()).toEqual({ reading: [], finished: [] })
  })

  it('adds a book to the currently-reading list', async () => {
    const store = createStore(file)
    const book = await store.add({ title: 'Dune', author: 'Frank Herbert', notes: 'Sand.' })

    const { reading, finished } = await store.list()
    expect(reading.map((b) => b.title)).toEqual(['Dune'])
    expect(finished).toEqual([])
    expect(book.finishedAt).toBeNull()
    expect(book.id).toBeTruthy()
  })

  it('trims whitespace and rejects a missing title', async () => {
    const store = createStore(file)
    const book = await store.add({ title: '  Dune  ', author: '  Herbert ' })
    expect(book.title).toBe('Dune')
    expect(book.author).toBe('Herbert')

    await expect(store.add({ title: '   ' })).rejects.toThrow(ValidationError)
  })

  it('moves a book to finished, and back again', async () => {
    const store = createStore(file)
    const { id } = await store.add({ title: 'Dune' })

    await store.finish(id)
    let lists = await store.list()
    expect(lists.reading).toEqual([])
    expect(lists.finished.map((b) => b.title)).toEqual(['Dune'])

    await store.reopen(id)
    lists = await store.list()
    expect(lists.reading.map((b) => b.title)).toEqual(['Dune'])
    expect(lists.finished).toEqual([])
  })

  it('keeps the original date when finishing twice', async () => {
    const store = createStore(file)
    const { id } = await store.add({ title: 'Dune' })

    const first = await store.finish(id, new Date('2026-01-01'))
    const second = await store.finish(id, new Date('2026-06-01'))
    expect(second.finishedAt).toBe(first.finishedAt)
  })

  it('lists most recently finished books first', async () => {
    const store = createStore(file)
    const a = await store.add({ title: 'A' })
    const b = await store.add({ title: 'B' })
    await store.finish(a.id, new Date('2026-01-01'))
    await store.finish(b.id, new Date('2026-05-01'))

    const { finished } = await store.list()
    expect(finished.map((x) => x.title)).toEqual(['B', 'A'])
  })

  it('saves notes and returns them by id', async () => {
    const store = createStore(file)
    const { id } = await store.add({ title: 'Dune' })

    await store.saveNotes(id, '  Spice is a metaphor.  ')
    expect((await store.get(id)).notes).toBe('Spice is a metaphor.')
  })

  it('returns null for an unknown id', async () => {
    const store = createStore(file)
    expect(await store.get('nope')).toBeNull()
    expect(await store.finish('nope')).toBeNull()
    expect(await store.saveNotes('nope', 'x')).toBeNull()
  })

  it('survives a restart by reloading the JSON file', async () => {
    const first = createStore(file)
    const { id } = await first.add({ title: 'Dune', author: 'Frank Herbert' })
    await first.finish(id)

    const second = createStore(file)
    const { finished } = await second.list()
    expect(finished.map((b) => b.title)).toEqual(['Dune'])

    const onDisk = JSON.parse(await readFile(file, 'utf8'))
    expect(onDisk.books).toHaveLength(1)
  })

