    const store = createStore(file)
    await Promise.all(
      Array.from({ length: 10 }, (_, i) => store.add({ title: `Book ${i}` })),
    )
    const { reading } = await store.list()
    expect(reading).toHaveLength(10)

    const onDisk = JSON.parse(await readFile(file, 'utf8'))
    expect(onDisk.books).toHaveLength(10)
  })
})

