import { describe, it, expect, beforeEach, afterEach } from 'vitest'
import { mkdtemp, rm } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { startServer } from '../src/server.js'

let dir
let server
let base

beforeEach(async () => {
  dir = await mkdtemp(join(tmpdir(), 'books-http-'))
  server = await startServer({ file: join(dir, 'books.json'), port: 0 })
  base = `http://127.0.0.1:${server.address().port}`
})

afterEach(async () => {
  await new Promise((done) => server.close(done))
  await rm(dir, { recursive: true, force: true })
})

const form = (fields) => ({
  method: 'POST',
  headers: { 'content-type': 'application/x-www-form-urlencoded' },
  body: new URLSearchParams(fields),
  redirect: 'manual',
})

async function addBook(fields) {
  const res = await fetch(`${base}/books`, form(fields))
  expect(res.status).toBe(303)
  return res.headers.get('location') // /books/:id
}

describe('the app', () => {
  it('shows both lists on the home page', async () => {
    const res = await fetch(base)
    const body = await res.text()
    expect(res.status).toBe(200)
    expect(body).toContain('Currently reading')
    expect(body).toContain('Finished')
  })

  it('adds a book from the form and redirects to its page', async () => {
    const location = await addBook({ title: 'Dune', author: 'Frank Herbert' })
    expect(location).toMatch(/^\/books\/[\w-]+$/)

    const page = await (await fetch(base + location)).text()
    expect(page).toContain('Dune')
    expect(page).toContain('Frank Herbert')
  })

  it('re-renders the form with an error when the title is blank', async () => {
    const res = await fetch(`${base}/books`, form({ title: '', author: 'Nobody' }))
    const body = await res.text()
    expect(res.status).toBe(400)
    expect(body).toContain('A title is required.')
    // The author the user already typed is preserved.
    expect(body).toContain('value="Nobody"')
  })

  it('marks a book finished and moves it between lists', async () => {
    const location = await addBook({ title: 'Dune' })
    const id = location.split('/').pop()

    const finish = await fetch(`${base}${location}/finish`, form({}))
    expect(finish.status).toBe(303)

    const home = await (await fetch(base)).text()
    expect(home).toContain('Finished ')
    // The "mark finished" button for this book is gone from the list.
    expect(home).not.toContain(`/books/${id}/finish`)
  })

  it('saves notes from the book page', async () => {
    const location = await addBook({ title: 'Dune' })
    await fetch(`${base}${location}/notes`, form({ notes: 'Spice is a metaphor.' }))

    const page = await (await fetch(base + location)).text()
    expect(page).toContain('Spice is a metaphor.')
  })

  it('serves a shareable link to a single book', async () => {
    const location = await addBook({ title: 'Dune', author: 'Frank Herbert' })

    // A fresh client with no session or cookies can read the same page.
    const res = await fetch(base + location, { headers: {} })
    expect(res.status).toBe(200)
    expect(await res.text()).toContain('Dune')
  })

  it('404s on an unknown book instead of crashing', async () => {
    const res = await fetch(`${base}/books/missing123`)
    expect(res.status).toBe(404)
    expect(await res.text()).toContain('No such book')
  })

  it('escapes HTML in user input', async () => {
    const location = await addBook({ title: '<script>alert(1)</script>' })
    const page = await (await fetch(base + location)).text()
    expect(page).not.toContain('<script>alert(1)</script>')
    expect(page).toContain('&lt;script&gt;')
  })
})

